node --input-type=module <<'NODE'
import { mkdir, readFile } from 'node:fs/promises'
import { createRequire } from 'node:module'
import { join } from 'node:path'
const runtime = join(process.env.HOME || '/home/runner', '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(await readFile(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= `:${(await readFile(join(runtime, 'display'), 'utf8')).trim()}`
const out = '/tmp/opencode/emberdeep-check'
await mkdir(out, { recursive: true })
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const defects = []
const desktop = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 })
desktop.on('pageerror', e => defects.push(e.message))
await desktop.goto('http://127.0.0.1:4173/', { waitUntil: 'load' })
await desktop.locator('#gameMap .tile').first().waitFor()
const initial = await desktop.evaluate(() => ({ title: document.title, tiles: document.querySelectorAll('#gameMap .tile').length, overflow: document.documentElement.scrollWidth > innerWidth, health: document.querySelector('#healthText').textContent }))
await desktop.locator('#gameMap .tile[data-x="3"][data-y="5"]').click()
const turnAfterMove = await desktop.locator('#turnCount').textContent()
if (initial.tiles !== 165 || turnAfterMove !== '001') throw new Error(`Gameplay smoke test failed: ${JSON.stringify({ initial, turnAfterMove })}`)
await desktop.screenshot({ path: `${out}/desktop.jpg`, type: 'jpeg', quality: 62 })
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true })
mobile.on('pageerror', e => defects.push(e.message))
await mobile.goto('http://127.0.0.1:4173/', { waitUntil: 'load' })
await mobile.locator('[data-move="right"]').click()
const mobileState = await mobile.evaluate(() => ({ width: document.documentElement.scrollWidth, viewport: innerWidth, controls: getComputedStyle(document.querySelector('.mobile-controls')).display, turn: document.querySelector('#turnCount').textContent }))
if (mobileState.width > mobileState.viewport || mobileState.controls === 'none' || mobileState.turn !== '001') throw new Error(`Mobile smoke test failed: ${JSON.stringify(mobileState)}`)
await mobile.screenshot({ path: `${out}/mobile.jpg`, type: 'jpeg', quality: 62 })
if (defects.length) throw new Error(`Browser errors: ${defects.join('; ')}`)
console.log(JSON.stringify({ initial, turnAfterMove, mobileState, screenshots: [`${out}/desktop.jpg`, `${out}/mobile.jpg`], defects }, null, 2))
await browser.close()
NODE

